import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Create container
  const root = new Group();
  root.position.set(-1.25, 1.6, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Geometry
  const geometry = new PlaneGeometry(1, 0.3, 64, 64); // horizontal row size

  // Material (placeholder, will be filled when textures load)
  const material = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'), // paper as base
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
  });

  // Create mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load textures asynchronously
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  texPromise.then((tex) => {
    material.mapNode = texture(uv(), tex);
    material.needsUpdate = true;
  });

  depthPromise.then((depthTex) => {
    // displacementScale = 0.15 scene units (as per spec)
    material.displacementNode = mul(texture(uv(), depthTex), float(0.15));
    material.needsUpdate = true;
  });

  // Interaction timelines storage
  const timelines = [];

  // Hover effect: rise-in (translate Y +0.15)
  function onHoverEnter() {
    const tl = gsap.timeline();
    tl.to(mesh.position, { y: mesh.position.y + 0.15, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  function onHoverLeave() {
    const tl = gsap.timeline();
    tl.to(mesh.position, { y: mesh.position.y - 0.15, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  // Click effect: emit navigation event
  function onClick() {
    ctx.emit('navigate', { to: 'hub-features' });
  }

  // Attach handlers to userData
  root.userData.handlers = {
    hover: (enter) => {
      if (enter) onHoverEnter();
      else onHoverLeave();
    },
    click: onClick,
  };

  // Apply any cinematic primitives defined in config
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const { name, params, trigger } = prim;
      const primInstance = ctx.primitives[name](root, params);
      primitiveCleanups.push(primInstance);
    }
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Cleanup primitives
    for (const p of primitiveCleanups) {
      if (p.cleanup) p.cleanup();
    }
  };

  return root;
}
